INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(100, 'actionable', '/ˈækʃənəbəl/', 'adjective', '{"zh-TW":["可行的；可採取行動的"],"en":["capable of being acted on; providing a basis for action"]}', NULL, 'actionable insights / actionable recommendation', '[{"en":"The report provides actionable recommendations for improvement.","zh-TW":"報告提供了可行的改進建議。"},{"en":"Good data analysis produces actionable insights for managers.","zh-TW":"良好的數據分析為管理者提供可採取行動的洞見。"}]', NULL, NULL, 4, 100, 951),
(101, 'activate', 'ˈæktɪveɪt', 'verb', '{"zh-TW":["啟動；激活","開啟"],"en":["to start something working","to put into operation"]}', NULL, 'activate an account/activate a feature', '[{"en":"Please activate your account to begin.","zh-TW":"請啟動您的帳戶以開始。"}]', '{"noun":"activation","adjective":"active","adverb":"actively"}', NULL, 3, 101, 813),
(102, 'active', 'ˈæktɪv', 'adjective', '{"zh-TW":["積極的；活躍的","主動的"],"en":["energetic and engaged","in operation"]}', NULL, 'active role/active member', '[{"en":"He plays an active role in the community.","zh-TW":"他在社區中扮演積極的角色。"}]', '{"noun":"activity","adverb":"actively"}', NULL, 2, 102, NULL),
(103, 'active learning', '/''æktɪv ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["主動學習；積極學習"],"en":["an approach to education that involves students actively participating rather than passively receiving information"]}', NULL, 'promote active learning / active learning strategy / active learning environment', '[{"en":"Active learning strategies include group discussions, problem-solving, and debates.","zh-TW":"主動學習策略包括小組討論、解決問題和辯論。"},{"en":"Teachers who use active learning techniques see higher student engagement.","zh-TW":"使用主動學習技術的教師看到更高的學生參與度。"}]', NULL, NULL, 5, 103, NULL),
(104, 'active listening', '/ˈæktɪv ˈlɪsənɪŋ/', 'noun', '{"zh-TW":["積極傾聽"],"en":["fully concentrating and responding thoughtfully to what a person is saying"]}', NULL, 'practice active listening / active listening skills', '[{"en":"Active listening is critical in customer service and negotiations.","zh-TW":"積極傾聽在客戶服務和談判中至關重要。"},{"en":"Managers who use active listening build stronger team relationships.","zh-TW":"使用積極傾聽的管理者建立了更強的團隊關係。"}]', NULL, NULL, 5, 104, NULL),
(105, 'active management', '/ˈæktɪv ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["主動管理"],"en":["an investment strategy where managers make specific investment decisions to outperform the market"]}', NULL, 'employ active management / active management fees', '[{"en":"Active management aims to beat benchmark returns through stock selection.","zh-TW":"主動管理旨在通過選股超越基準回報。"},{"en":"Higher fees for active management must be justified by superior returns.","zh-TW":"主動管理的較高費用必須通過卓越回報來證明合理性。"}]', '{"opposite":"passive management"}', NULL, 5, 105, NULL),
(106, 'active recovery', '/''æktɪv rɪˌkʌvəri/', 'noun', '{"zh-TW":["主動恢復；積極恢復訓練"],"en":["light physical activity done on rest days to aid muscle recovery without causing additional fatigue"]}', NULL, 'use active recovery / active recovery day / active recovery exercise', '[{"en":"She went for an easy swim as active recovery after the intense marathon race.","zh-TW":"她在激烈的馬拉松比賽後進行了一次輕鬆的游泳作為主動恢復。"},{"en":"Active recovery methods like yoga and walking are preferred by many elite athletes.","zh-TW":"許多精英運動員喜歡瑜伽和步行等主動恢復方法。"}]', '{"adjective":"active","verb":"recover"}', NULL, 5, 106, NULL),
(107, 'actual', 'ˈæktʃuəl', 'adjective', '{"zh-TW":["實際的；真正的","現實的"],"en":["existing in reality","real"]}', NULL, 'actual cost/actual results', '[{"en":"The actual cost exceeded the budget.","zh-TW":"實際成本超出了預算。"}]', '{"noun":"actuality","adverb":"actually"}', NULL, 2, 107, 814),
(108, 'actualize', '/ˈæktʃuəlaɪz/', 'verb', '{"zh-TW":["實現；使現實化"],"en":["to make something real or actual"]}', NULL, 'actualize potential / actualize a vision / actualize goals', '[{"en":"The training program helps employees actualize their professional potential.","zh-TW":"培訓計畫幫助員工實現其專業潛力。"},{"en":"The project team worked to actualize the architect''s creative vision.","zh-TW":"項目團隊努力實現建築師的創意願景。"}]', '{"noun":"actualization","adjective":"actualized"}', NULL, 3, 108, NULL),
(109, 'actuary', '/ˈæktʃuəri/', 'noun', '{"zh-TW":["精算師"],"en":["a person who uses mathematics and statistics to assess financial risks"]}', NULL, 'qualified actuary / insurance actuary / pension actuary', '[{"en":"An actuary calculates premiums based on statistical risk models.","zh-TW":"精算師根據統計風險模型計算保費。"},{"en":"Pension fund actuaries must forecast long-term obligations accurately.","zh-TW":"養老基金精算師必須準確預測長期義務。"}]', '{"noun2":"actuarial","adjective":"actuarial"}', NULL, 3, 109, NULL),
(110, 'actuator', '/ˈæktʃueɪtər/', 'noun', '{"zh-TW":["執行器；致動器"],"en":["a device that converts energy into physical movement to control a system"]}', NULL, 'control an actuator / linear actuator / smart actuator', '[{"en":"The robot''s arm is controlled by precision actuators.","zh-TW":"機器人的手臂由精密執行器控制。"},{"en":"Smart actuators in HVAC systems automatically adjust temperature.","zh-TW":"暖通空調系統中的智能執行器自動調節溫度。"}]', NULL, NULL, 3, 110, NULL),
(111, 'acuity', '/əˈkjuːɪti/', 'noun', '{"zh-TW":["敏銳；清晰度"],"en":["sharpness or keenness of thought, vision, or hearing"]}', NULL, 'visual acuity / mental acuity / business acuity', '[{"en":"Her mental acuity was remarkable even at an advanced age.","zh-TW":"她在高齡時仍展現出卓越的思維敏銳度。"},{"en":"Market acuity allows leaders to spot opportunities before competitors do.","zh-TW":"市場敏銳度使領導者能夠在競爭對手之前發現機會。"}]', NULL, NULL, 2, 111, NULL),
(112, 'acumen', '/ˈækjʊmən/', 'noun', '{"zh-TW":["敏銳；洞察力"],"en":["the ability to make good judgments and quick decisions"]}', NULL, 'business acumen / financial acumen / sharp acumen', '[{"en":"Her business acumen helped the company grow rapidly.","zh-TW":"她的商業敏銳度幫助公司快速成長。"},{"en":"He demonstrated remarkable acumen in identifying market trends.","zh-TW":"他在識別市場趨勢方面展現出卓越的洞察力。"}]', NULL, NULL, 2, 112, NULL),
(113, 'acupuncture', '/ˈækjʊˌpʌŋktʃər/', 'noun', '{"zh-TW":["針灸"],"en":["a therapy involving inserting needles into the body at specific points"]}', NULL, 'receive acupuncture / acupuncture treatment', '[{"en":"She tried acupuncture to relieve chronic back pain.","zh-TW":"她嘗試針灸來緩解慢性背痛。"},{"en":"Acupuncture is widely used in traditional Chinese medicine.","zh-TW":"針灸在中醫中被廣泛使用。"}]', '{"adjective":"acupuncture"}', NULL, 4, 113, NULL),
(114, 'acupuncturist', '/ˌækjʊˈpʌŋktʃərɪst/', 'noun', '{"zh-TW":["針灸師"],"en":["a practitioner who performs acupuncture treatment"]}', NULL, 'licensed acupuncturist / qualified acupuncturist / consult an acupuncturist', '[{"en":"The acupuncturist treated her chronic back pain with fine needles.","zh-TW":"針灸師用細針治療她的慢性背痛。"},{"en":"An acupuncturist must complete specialized training to practice.","zh-TW":"針灸師必須完成專業培訓才能執業。"}]', NULL, NULL, 5, 114, NULL),
(115, 'acute', '/''əˈkjuːt/', 'adjective', '{"zh-TW":["急性的；敏銳的；嚴重的"],"en":["of a bad, difficult, or unwelcome situation or phenomenon; present to a severe or intense degree"]}', NULL, 'acute shortage / acute awareness / acute sense', '[{"en":"There is an acute shortage of qualified engineers in the technology sector.","zh-TW":"科技行業合格工程師嚴重短缺。"},{"en":"She has an acute awareness of market trends that helps her make timely decisions.","zh-TW":"她對市場趨勢有敏銳的洞察力，幫助她及時做出決策。"}]', '{"adverb":"acutely","noun":"acuteness"}', NULL, 2, 115, NULL),
(116, 'ad hoc', '/ˌæd ˈhɒk/', 'adjective', '{"zh-TW":["臨時的；特別的"],"en":["created or done for a specific purpose without prior planning"]}', NULL, 'ad hoc meeting / ad hoc committee / ad hoc arrangement', '[{"en":"An ad hoc committee was formed to handle the merger negotiations.","zh-TW":"一個臨時委員會成立以處理合併談判。"},{"en":"Ad hoc decisions should not replace a formal strategic process.","zh-TW":"臨時決策不應取代正式的戰略流程。"}]', NULL, NULL, 2, 116, NULL),
(117, 'ad valorem tax', '/æd vəˈlɔːrəm tæks/', 'noun', '{"zh-TW":["從價稅"],"en":["a tax based on the assessed value of a transaction, typically a percentage"]}', NULL, 'apply an ad valorem tax / ad valorem tax rate', '[{"en":"Import duties are often structured as an ad valorem tax on the goods'' value.","zh-TW":"進口關稅通常以貨物價值的從價稅形式徵收。"},{"en":"An ad valorem tax rate of 15% applies to all luxury goods imported.","zh-TW":"15%的從價稅率適用於所有進口奢侈品。"}]', NULL, NULL, 5, 117, NULL),
(118, 'adamant', '/''ædəmənt/', 'adjective', '{"zh-TW":["堅定不移的；不為所動的"],"en":["refusing to be persuaded or to change one''s mind"]}', NULL, 'adamant refusal / remain adamant / be adamant about', '[{"en":"The manager was adamant that the deadline could not be extended.","zh-TW":"管理者堅定地認為截止日期不能延長。"},{"en":"She was adamant about maintaining quality standards despite the budget pressure.","zh-TW":"儘管有預算壓力，她仍堅定不移地堅持質量標準。"}]', '{"adverb":"adamantly"}', NULL, 3, 118, NULL),
(119, 'adapt', '/əˈdæpt/', 'verb', '{"zh-TW":["適應；改編"],"en":["to adjust to new conditions","to modify for a new purpose"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"apt","meaning":"fit (適合)"},"logic":"朝向適合，即「適應」。"}', 'adapt to changes/environment; adapt to / adapt a novel', '[{"en":"Employees must adapt to new technologies quickly.","zh-TW":"員工必須快速適應新技術。"},{"en":"The novel was adapted into a film.","zh-TW":"這部小說被改編成電影。"},{"en":"Animals must adapt to their environment.","zh-TW":"動物必須適應環境。"},{"en":"The novel was adapted into a film.","zh-TW":"這本小說被改編成電影。"}]', '{"noun":"adaptation","adjective":"adaptable"}', NULL, 2, 119, 815),
(120, 'adaptability', '/əˌdæptəˈbɪlɪti/', 'noun', '{"zh-TW":["適應能力"],"en":["the ability to adjust to new conditions or requirements quickly"]}', NULL, 'demonstrate adaptability / adaptability in the workplace / build adaptability', '[{"en":"Adaptability is increasingly valued as business environments change rapidly.","zh-TW":"隨著商業環境快速變化，適應能力日益受到重視。"},{"en":"Her adaptability made her an asset during the company restructuring.","zh-TW":"她的適應能力使她在公司重組期間成為寶貴資產。"}]', '{"adjective":"adaptable","verb":"adapt"}', NULL, 4, 120, 742),
(121, 'adaptive algorithm', '/əˈdæptɪv ˈælɡərɪðəm/', 'noun', '{"zh-TW":["自適應算法"],"en":["an algorithm that adjusts its behavior in response to input data"]}', NULL, 'develop an adaptive algorithm / apply an adaptive algorithm / use an adaptive algorithm', '[{"en":"Adaptive algorithms improve recommendation accuracy over time.","zh-TW":"自適應算法隨時間的推移提高推薦準確性。"},{"en":"The system uses an adaptive algorithm to optimize energy consumption.","zh-TW":"系統使用自適應算法來優化能源消耗。"}]', NULL, NULL, 5, 121, NULL),
(122, 'add', '/æd/', 'verb', '{"zh-TW":["增加；添加","增加；添加；補充說"],"en":["to put something with something else","to put something with another thing; to say something more"]}', NULL, 'add up / add to; add up (加總) / add to (增添)', '[{"en":"Add some sugar to my coffee.","zh-TW":"在我的咖啡裡加些糖。"},{"en":"The numbers don''t add up.","zh-TW":"這些數字加起來不對。"},{"en":"Please add your name to the list.","zh-TW":"請把你的名字加到名單上。"},{"en":"The rain added to our difficulties.","zh-TW":"雨水增加了我們的困難。"}]', '{"noun":"addition","adjective":"additional","adverb":"additionally"}', NULL, 1, 122, NULL),
(123, 'addendum', '/əˈdɛndəm/', 'noun', '{"zh-TW":["附錄；補充條款"],"en":["an item added to a contract or document"]}', NULL, 'add an addendum / contract addendum', '[{"en":"An addendum was attached to the agreement outlining new terms.","zh-TW":"協議附上了說明新條款的附錄。"},{"en":"Please sign the addendum to confirm the changes.","zh-TW":"請簽署附錄以確認更改。"}]', '{"plural":"addenda"}', NULL, 3, 123, NULL),
(124, 'additional', '/əˈdɪʃənl/', 'adjective', '{"zh-TW":["額外的；附加的"],"en":["extra; more than what is usual or expected"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ional","meaning":"relating to (有關的)"},"logic":"額外給予的，即「額外的」。"}', 'additional cost/information/support', '[{"en":"There will be an additional charge for express delivery.","zh-TW":"快遞將收取額外費用。"},{"en":"Do you need any additional information?","zh-TW":"您需要任何額外資訊嗎？"}]', '{"noun":"addition","adverb":"additionally"}', NULL, 4, 124, 816),
(125, 'address', '/əˈdres/', 'verb', '{"zh-TW":["【主要意義-名詞】地址；住址","【次要意義-動詞】處理；著手解決（問題）","【次要意義-動詞】向……發表演說；稱呼"],"en":["[primary - noun] the details of where someone lives or works","[secondary - verb] to deal with or direct attention to a problem or issue","[secondary - verb] to speak formally to a group or person"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dress","meaning":"direct (引導)"},"logic":"朝向引導，即「處理；致辭」。"}', 'address a problem / address concerns / address the audience / address the issue', '[{"en":"The new policy aims to address the growing concerns about workplace safety.","zh-TW":"新政策旨在解決對工作場所安全日益增長的擔憂。"},{"en":"The CEO addressed shareholders at the annual general meeting.","zh-TW":"執行長在年度股東大會上向股東發表演說。"},{"en":"We need to address the budget shortfall before the end of the quarter.","zh-TW":"我們需要在季度結束前解決預算短缺問題。"}]', '{"noun":"addressee","adjective":"addressable"}', '動詞 address = 「處理/解決」某問題，是 TOEIC 最高頻動詞之一，句型 address + issue/concern/problem 極為常見，考生常誤以為只有「地址」的意思。', 3, 125, 251),
(126, 'adept', '/əˈdept/', 'adjective', '{"zh-TW":["熟練的；精通的"],"en":["highly skilled or proficient at something"]}', NULL, 'adept at / adept negotiator / become adept', '[{"en":"She is adept at navigating complex organizational dynamics.","zh-TW":"她擅長處理複雜的組織動態。"},{"en":"He became adept at managing multiple projects simultaneously.","zh-TW":"他在同時管理多個項目方面變得非常熟練。"}]', '{"adverb":"adeptly","noun":"adeptness"}', NULL, 2, 126, NULL),
(127, 'adequate', '/ˈædɪkwət/', 'adjective', '{"zh-TW":["足夠的；適當的"],"en":["sufficient for a specific need or requirement","sufficient for a specific requirement"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"equ","meaning":"equal (相等)"},"suffix":{"text":"-ate","meaning":"having quality (具有)"},"logic":"朝向相等，即「足夠的」。"}', 'adequate supply/funding/preparation; adequate supply / adequate preparation', '[{"en":"The budget is barely adequate for the project.","zh-TW":"預算勉強夠用於該專案。"},{"en":"Ensure adequate ventilation in the workspace.","zh-TW":"確保工作空間有充足的通風。"},{"en":"The hotel room was adequate for our needs.","zh-TW":"飯店房間足以滿足我們的需求。"},{"en":"Make sure you have adequate insurance.","zh-TW":"確保你有足夠的保險。"}]', '{"noun":"adequacy","adverb":"adequately"}', NULL, 3, 127, 69),
(128, 'adhere', '/ədˈhɪər/', 'verb', '{"zh-TW":["遵守；堅持","黏附"],"en":["to follow rules or guidelines closely","to stick firmly to a surface"]}', '{"prefix":{"text":"ad-","meaning":"to (朝向)"},"root":{"text":"here","meaning":"stick (黏)"},"logic":"朝向黏住，即「遵守、黏附」。"}', 'adhere to rules/policies/standards', '[{"en":"All employees must adhere to the company''s code of conduct.","zh-TW":"所有員工都必須遵守公司行為準則。"},{"en":"Please adhere to the safety guidelines at all times.","zh-TW":"請隨時遵守安全指南。"}]', '{"noun":"adherence","adjective":"adherent"}', NULL, 2, 128, 636),
(129, 'adjacent', '/əˈdʒeɪsnt/', 'adjective', '{"zh-TW":["鄰近的；毗鄰的"],"en":["next to or near something"]}', '{"prefix":{"text":"ad-","meaning":"near (靠近)"},"root":{"text":"jac","meaning":"lie (躺)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"躺在旁邊的，即「鄰近的」。"}', 'adjacent to / adjacent building/room', '[{"en":"The parking lot is adjacent to the main building.","zh-TW":"停車場緊鄰主建築。"},{"en":"We booked adjacent conference rooms for the event.","zh-TW":"我們為活動預訂了相鄰的會議室。"}]', NULL, NULL, 3, 129, 3),
(130, 'adjourn', '/əˈdʒɜːrn/', 'verb', '{"zh-TW":["休會；延期"],"en":["to suspend a meeting or session to a later time"]}', NULL, 'adjourn the meeting / adjourn until next week', '[{"en":"The chairperson adjourned the meeting after three hours.","zh-TW":"主席在三小時後宣布休會。"},{"en":"The hearing was adjourned pending new evidence.","zh-TW":"聽證會因等待新證據而被延期。"}]', '{"noun":"adjournment","adjective":"adjourned"}', NULL, 3, 130, 817),
(131, 'adjournment', '/əˈdʒɜːrnmənt/', 'noun', '{"zh-TW":["休會；延期"],"en":["the act of suspending a meeting to a later time"]}', NULL, 'motion for adjournment / meeting adjournment', '[{"en":"The adjournment allowed more time for preparation.","zh-TW":"休會提供了更多的準備時間。"},{"en":"The chairperson called for an adjournment after two hours.","zh-TW":"主席在兩小時後宣布休會。"}]', '{"verb":"adjourn"}', NULL, 4, 131, 976),
(132, 'adjudicate', '/əˈdʒuːdɪkeɪt/', 'verb', '{"zh-TW":["裁決；判決"],"en":["to make a formal judgment or decision about a dispute"]}', NULL, 'adjudicate a dispute / adjudicate a claim / adjudicate a case', '[{"en":"The tribunal adjudicated the labor dispute in favor of the workers.","zh-TW":"裁判所就勞資糾紛作出有利工人的裁決。"},{"en":"Regulatory bodies adjudicate complaints about unfair market practices.","zh-TW":"監管機構裁決關於不公平市場行為的投訴。"}]', '{"noun":"adjudication","noun2":"adjudicator"}', NULL, 4, 132, NULL),
(133, 'adjust', '/əˈdʒʌst/', 'verb', '{"zh-TW":["調整；校準","調整"],"en":["to alter slightly to achieve the desired result","to alter slightly to achieve a desired result"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"just","meaning":"right (正確)"},"logic":"朝向正確，即「調整」。"}', 'adjust settings/schedule/strategy; adjust settings / adjust to', '[{"en":"We need to adjust our strategy to meet market demands.","zh-TW":"我們需要調整策略以滿足市場需求。"},{"en":"The price has been adjusted for inflation.","zh-TW":"價格已根據通膨進行調整。"},{"en":"You can adjust the temperature with this dial.","zh-TW":"你可以用這個旋鈕調整溫度。"},{"en":"It took time to adjust to the new schedule.","zh-TW":"適應新時間表需要一些時間。"}]', '{"noun":"adjustment","adjective":"adjustable"}', NULL, 2, 133, 818),
(134, 'adjusting entry', '/əˈdʒʌstɪŋ ˈentri/', 'noun', '{"zh-TW":["調整分錄"],"en":["an accounting entry made at the end of a period to update accounts"]}', NULL, 'make an adjusting entry / adjusting entry for accruals', '[{"en":"Adjusting entries ensure that revenues and expenses are properly matched.","zh-TW":"調整分錄確保收入和費用的適當配比。"},{"en":"The accountant made adjusting entries to correct the monthly accounts.","zh-TW":"會計師進行了調整分錄以修正月度帳目。"}]', NULL, NULL, 5, 134, NULL),
(135, 'administer', '/ədˈmɪnɪstər/', 'verb', '{"zh-TW":["管理；執行","施予"],"en":["to manage or direct","to give or apply formally","to manage or be responsible for"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"minister","meaning":"serve (服務)"},"logic":"朝向服務，即「管理」。"}', 'administer a program/test/policy; administer a program / administer medicine', '[{"en":"The HR department administers the benefits program.","zh-TW":"人力資源部門管理福利計畫。"},{"en":"The exam will be administered next Monday.","zh-TW":"考試將於下週一進行。"},{"en":"She administers the company''s finances.","zh-TW":"她管理公司的財務。"},{"en":"The nurse administered the medication.","zh-TW":"護理師給予了藥物。"}]', '{"noun":"administration","adjective":"administrative","noun2":"administrator"}', NULL, 4, 135, 638),
(136, 'administration', '/ədˌmɪnɪˈstreɪʃən/', 'noun', '{"zh-TW":["行政；管理"],"en":["the management and organization of a business or institution"]}', NULL, 'business administration / public administration / administration team', '[{"en":"The administration team handles all scheduling and correspondence.","zh-TW":"行政團隊處理所有排程和信件往來。"},{"en":"A degree in business administration is highly valued by employers.","zh-TW":"工商管理學位受到雇主的高度重視。"}]', '{"verb":"administer","adjective":"administrative","noun":"administrator"}', NULL, 5, 136, 494),
(137, 'administrative assistant', '/ədˈmɪnɪstrətɪv əˈsɪstənt/', 'noun', '{"zh-TW":["行政助理"],"en":["a person who provides organizational support to an office"]}', NULL, 'hire an administrative assistant / senior administrative assistant', '[{"en":"The administrative assistant scheduled all meetings.","zh-TW":"行政助理安排了所有會議。"},{"en":"A reliable administrative assistant is essential for a smooth operation.","zh-TW":"可靠的行政助理對於順暢運作至關重要。"}]', NULL, NULL, 5, 137, NULL),
(138, 'administrative expense', '/ədˈmɪnɪstrətɪv ɪkˈspens/', 'noun', '{"zh-TW":["行政費用"],"en":["costs associated with the general management and administration of a company"]}', NULL, 'reduce administrative expenses / administrative expense ratio', '[{"en":"Administrative expenses were cut by consolidating back-office functions.","zh-TW":"通過整合後台職能降低了行政費用。"},{"en":"Administrative expenses include salaries of management and office overhead.","zh-TW":"行政費用包括管理人員薪資和辦公室間接費用。"}]', NULL, NULL, 5, 138, NULL),
(139, 'administrative overhead', '/ədˈmɪnɪstrətɪv ˈoʊvərhed/', 'noun', '{"zh-TW":["行政間接費用"],"en":["indirect costs related to managing and running an organization"]}', NULL, 'reduce administrative overhead / administrative overhead costs', '[{"en":"Reducing administrative overhead was a key part of the cost-cutting plan.","zh-TW":"降低行政間接費用是削減成本計劃的重要組成部分。"},{"en":"Administrative overhead includes HR, finance, and legal department costs.","zh-TW":"行政間接費用包括人力資源、財務和法務部門的成本。"}]', NULL, NULL, 5, 139, NULL),
(140, 'admire', '/ədˈmaɪər/', 'verb', '{"zh-TW":["欽佩；讚賞"],"en":["to regard with respect or warm approval"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"mire","meaning":"wonder (驚嘆)"},"logic":"朝向某事物驚嘆，即「欽佩」。"}', 'admire someone for / greatly admire', '[{"en":"I admire her courage and determination.","zh-TW":"我欽佩她的勇氣和決心。"},{"en":"Everyone admires his dedication to work.","zh-TW":"每個人都讚賞他對工作的奉獻。"}]', '{"noun":"admiration","adjective":"admirable","noun2":"admirer"}', NULL, 2, 140, NULL),
(141, 'admissibility', '/ədˌmɪsəˈbɪlɪti/', 'noun', '{"zh-TW":["可採納性；可受理性"],"en":["the quality of being acceptable or valid in a court of law"]}', NULL, 'challenge admissibility / admissibility of evidence / rule on admissibility', '[{"en":"The judge ruled on the admissibility of the digital evidence.","zh-TW":"法官就數字證據的可採納性作出裁定。"},{"en":"Admissibility of evidence is governed by strict procedural rules.","zh-TW":"證據的可採納性受嚴格的程序規則約束。"}]', '{"adjective":"admissible","antonym":"inadmissible"}', NULL, 5, 141, NULL),
(142, 'admission', '/ədˈmɪʃn/', 'noun', '{"zh-TW":["入場；入學","承認"],"en":["the process of being allowed to enter","a confession that something is true"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"被送入的動作，即「入場」。"}', 'admission fee/requirements/process', '[{"en":"Admission to the conference is free for members.","zh-TW":"會員可免費參加會議。"},{"en":"The admission requirements include a bachelor''s degree.","zh-TW":"入學要求包括學士學位。"}]', '{"verb":"admit"}', NULL, 3, 142, 253),
(143, 'admit', '/ədˈmɪt/', 'verb', '{"zh-TW":["承認；准許進入"],"en":["to agree something is true unwillingly","to agree that something is true; to allow to enter"]}', NULL, 'admit to / be admitted to; admit to + V-ing / be admitted to', '[{"en":"He admitted making a mistake.","zh-TW":"他承認犯了錯。"},{"en":"She was admitted to the hospital.","zh-TW":"她被送進了醫院。"},{"en":"He admitted making a mistake.","zh-TW":"他承認犯了一個錯誤。"}]', '{"noun":"admission","adjective":"admissible"}', NULL, 2, 143, NULL),
(144, 'adopt', '/əˈdɒpt/', 'verb', '{"zh-TW":["採用；採納","收養","採用；收養"],"en":["to start using a new method or idea","to legally take another''s child","to take up or start to use"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"opt","meaning":"choose (選擇)"},"logic":"朝向選擇，即「採用」。"}', 'adopt a policy/strategy/approach; adopt a policy / adopt a child', '[{"en":"The company adopted a new remote work policy.","zh-TW":"公司採用了新的遠端工作政策。"},{"en":"Several countries have adopted similar regulations.","zh-TW":"幾個國家已採用了類似法規。"},{"en":"The company adopted a new marketing strategy.","zh-TW":"公司採用了新的行銷策略。"},{"en":"They decided to adopt a child.","zh-TW":"他們決定領養一個孩子。"}]', '{"noun":"adoption","adjective":"adopted"}', NULL, 2, 144, 254),
(145, 'advance', '/ədˈvɑːns/', 'verb', '{"zh-TW":["推進；前進","預付","前進；推進"],"en":["to move forward or make progress","to pay money before it is due","to move forward","to make progress"]}', '{"prefix":{"text":"ad-","meaning":"forward (向前)"},"root":{"text":"vance","meaning":"go (走)"},"logic":"向前走，即「推進」。"}', 'advance knowledge/career/payment; advance in career / advance payment / in advance', '[{"en":"Technology continues to advance at a rapid pace.","zh-TW":"技術持續快速進步。"},{"en":"Can you advance me next month''s salary?","zh-TW":"你可以預付我下個月的薪水嗎？"},{"en":"Technology continues to advance rapidly.","zh-TW":"科技持續快速進步。"},{"en":"Please pay in advance.","zh-TW":"請預先付款。"}]', '{"noun":"advancement","adjective":"advanced"}', NULL, 3, 145, 70),
(146, 'advance notice', '/ədˈvɑːns ˈnoʊtɪs/', 'noun', '{"zh-TW":["提前通知"],"en":["notification given ahead of a required action or event"]}', NULL, 'provide advance notice / advance notice requirement', '[{"en":"The contract requires 60 days advance notice for termination.","zh-TW":"合約要求提前60天通知終止。"},{"en":"Employees must give advance notice before taking extended leave.","zh-TW":"員工在請長假前必須提前通知。"}]', NULL, NULL, 5, 146, NULL),
(147, 'advance payment', '/ədˈvɑːns ˈpeɪmənt/', 'noun', '{"zh-TW":["預付款；訂金"],"en":["payment made before goods or services are delivered"]}', NULL, 'require advance payment / advance payment terms', '[{"en":"A 30% advance payment is required before production begins.","zh-TW":"生產開始前需要支付30%的預付款。"},{"en":"The client made an advance payment to secure the delivery slot.","zh-TW":"客戶提前付款以確保交貨時間槽。"}]', NULL, NULL, 5, 147, NULL),
(148, 'advance payment guarantee', '/ədˈvɑːns ˈpeɪmənt ˌɡærənˈtiː/', 'noun', '{"zh-TW":["預付款保函"],"en":["a guarantee ensuring advance payments are returned if a contract is not fulfilled"]}', NULL, 'issue an advance payment guarantee / advance payment guarantee terms', '[{"en":"The contractor provided an advance payment guarantee to the client.","zh-TW":"承包商向客戶提供了預付款保函。"},{"en":"An advance payment guarantee protects the buyer''s initial investment.","zh-TW":"預付款保函保護了買方的初始投資。"}]', NULL, NULL, 5, 148, NULL),
(149, 'advantage', '/ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["優勢；利益"],"en":["a condition giving a greater chance of success"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vant","meaning":"before (在前)"},"suffix":{"text":"-age","meaning":"state (狀態)"},"logic":"在前面的狀態，即「優勢」。"}', 'competitive advantage / take advantage of', '[{"en":"Our competitive advantage lies in customer service.","zh-TW":"我們的競爭優勢在於客戶服務。"},{"en":"Take advantage of the early-bird discount.","zh-TW":"把握早鳥折扣的機會。"}]', '{"adjective":"advantageous"}', NULL, 3, 149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(150, 'adventure tourism', '/''ədˈventʃər ˌtʊərɪzəm/', 'noun', '{"zh-TW":["冒險旅遊"],"en":["tourism involving activities that require physical exertion, such as hiking, skydiving, or rafting"]}', NULL, 'promote adventure tourism / adventure tourism operator / extreme adventure tourism', '[{"en":"Adventure tourism has grown rapidly as travelers seek more thrilling experiences.","zh-TW":"隨著旅行者尋求更刺激的體驗，冒險旅遊迅速增長。"},{"en":"The region is a popular destination for adventure tourism, offering rafting and climbing.","zh-TW":"該地區是冒險旅遊的熱門目的地，提供漂流和攀岩活動。"}]', NULL, NULL, 5, 150, NULL),
(151, 'adversarial', '/ˌædvɜːˈseəriəl/', 'adjective', '{"zh-TW":["對抗性的；敵對的"],"en":["involving opposition or conflict between two parties"]}', NULL, 'adversarial relationship / adversarial process / adversarial system', '[{"en":"Adversarial legal proceedings pit opposing lawyers against each other.","zh-TW":"對抗性法律程序使對立雙方律師相互較量。"},{"en":"The adversarial relationship between management and unions hurt productivity.","zh-TW":"管理層與工會之間的對抗性關係損害了生產力。"}]', '{"adverb":"adversarially","noun":"adversary"}', NULL, 4, 151, NULL),
(152, 'adverse', '/ˈædvɜːrs/', 'adjective', '{"zh-TW":["不利的；有害的"],"en":["preventing success or development; harmful"]}', NULL, 'adverse conditions / adverse effect / adverse reaction', '[{"en":"Adverse weather conditions delayed the shipment by three days.","zh-TW":"惡劣的天氣條件使貨物延誤了三天。"},{"en":"The price increase had an adverse effect on sales volume.","zh-TW":"價格上漲對銷售量產生了不利影響。"}]', '{"adverb":"adversely","noun":"adversity"}', NULL, 3, 152, NULL),
(153, 'adverse conditions', '/ədˈvɜːrs kənˈdɪʃənz/', 'noun', '{"zh-TW":["不利條件；惡劣條件"],"en":["circumstances that are negative or harmful to business operations"]}', NULL, 'face adverse conditions / operate under adverse conditions', '[{"en":"Sales declined due to adverse market conditions during the quarter.","zh-TW":"由於本季度不利的市場條件，銷售額下降了。"},{"en":"The company showed resilience in the face of adverse economic conditions.","zh-TW":"公司在面對不利的經濟條件時表現出了韌性。"}]', '{"adjective":"adverse"}', NULL, 5, 153, NULL),
(154, 'adverse event', '/ˈædvɜːrs ɪˈvent/', 'noun', '{"zh-TW":["不良事件"],"en":["an unwanted incident in a clinical trial or medical treatment"]}', NULL, 'report an adverse event / serious adverse event / adverse event monitoring', '[{"en":"The clinical trial was paused following several serious adverse events.","zh-TW":"在幾起嚴重不良事件之後，臨床試驗暫停了。"},{"en":"Healthcare workers must document all adverse events for regulatory review.","zh-TW":"醫療工作者必須記錄所有不良事件以供監管審查。"}]', NULL, NULL, 5, 154, NULL),
(155, 'adverse reaction', '/ˈædvɜːrs riˈækʃən/', 'noun', '{"zh-TW":["不良反應；副作用"],"en":["an unintended harmful response to a drug or treatment"]}', NULL, 'report an adverse reaction / adverse drug reaction / monitor for adverse reactions', '[{"en":"The patient reported an adverse reaction to the new medication.","zh-TW":"患者報告了對新藥物的不良反應。"},{"en":"Clinical trials closely monitor adverse reactions to ensure patient safety.","zh-TW":"臨床試驗密切監測不良反應以確保患者安全。"}]', NULL, NULL, 5, 155, NULL),
(156, 'adverse selection', '/ˈædvɜːrs sɪˈlekʃən/', 'noun', '{"zh-TW":["逆向選擇"],"en":["a market process in which undesired results occur when buyers and sellers have asymmetric information"]}', NULL, 'problem of adverse selection / adverse selection in insurance / reduce adverse selection', '[{"en":"Adverse selection in health insurance occurs when sicker people are more likely to buy coverage.","zh-TW":"健康保險中的逆向選擇發生在病情較重的人更有可能購買保障的情況下。"},{"en":"Mandatory insurance requirements reduce adverse selection by including healthy individuals.","zh-TW":"強制保險要求通過納入健康個體來減少逆向選擇。"}]', NULL, NULL, 5, 156, NULL),
(157, 'advertise', '/ˈædvətaɪz/', 'verb', '{"zh-TW":["做廣告；宣傳"],"en":["to describe a product in media to promote sales"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vert","meaning":"turn (轉向)"},"suffix":{"text":"-ise","meaning":"to make (使)"},"logic":"使人轉向注意，即「做廣告」。"}', 'advertise a product/position/service', '[{"en":"The company advertises heavily on social media.","zh-TW":"公司在社群媒體上大量做廣告。"},{"en":"The position was advertised in major newspapers.","zh-TW":"該職位在主要報紙上刊登廣告。"}]', '{"noun":"advertisement","noun2":"advertiser"}', NULL, 3, 157, 819),
(158, 'advertisement', '/ədˈvɜːrtɪsmənt/', 'noun', '{"zh-TW":["廣告"],"en":["a notice or announcement promoting a product or service"]}', NULL, 'run an advertisement / television advertisement', '[{"en":"The advertisement campaign reached millions of viewers.","zh-TW":"廣告活動觸達了數百萬觀眾。"},{"en":"She designed an eye-catching advertisement for the new product.","zh-TW":"她為新產品設計了引人注目的廣告。"}]', '{"verb":"advertise","noun":"advertiser","adjective":"advertised"}', NULL, 5, 158, NULL),
(159, 'advertising budget', '/ˈædvətaɪzɪŋ ˈbʌdʒɪt/', 'noun', '{"zh-TW":["廣告預算"],"en":["the amount of money allocated for advertising and promotional activities"]}', NULL, 'set an advertising budget / advertising budget allocation', '[{"en":"The advertising budget was increased by 25% to support the product launch.","zh-TW":"廣告預算增加了25%以支持產品發布。"},{"en":"A well-managed advertising budget maximizes return on marketing spend.","zh-TW":"管理良好的廣告預算最大化了行銷支出的回報。"}]', NULL, NULL, 5, 159, NULL),
(160, 'advice', 'ədˈvaɪs', 'noun', '{"zh-TW":["建議；忠告","意見"],"en":["recommendation about what to do","guidance"]}', NULL, 'seek advice/give advice', '[{"en":"She sought advice from a specialist.","zh-TW":"她向專家尋求建議。"}]', '{"verb":"advise","adjective":"advisable","adverb":"advisably"}', NULL, 2, 160, NULL),
(161, 'advise', '/ədˈvaɪz/', 'verb', '{"zh-TW":["建議；勸告"],"en":["to give counsel or recommendations"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vise","meaning":"see (看)"},"logic":"朝向看清楚，即「建議」。"}', 'advise sb to do / advise against', '[{"en":"I would advise you to review the contract carefully.","zh-TW":"我建議你仔細審閱合約。"},{"en":"The consultant advised against the merger.","zh-TW":"顧問建議不要進行合併。"}]', '{"noun":"advice","noun2":"adviser","adjective":"advisable"}', NULL, 2, 161, NULL),
(162, 'advisory', '/ədˈvaɪzəri/', 'adjective', '{"zh-TW":["顧問的；諮詢的"],"en":["having the function of giving advice but not making decisions"]}', NULL, 'advisory role / advisory board / advisory committee', '[{"en":"She serves in an advisory role to the board of directors.","zh-TW":"她擔任董事會的顧問角色。"},{"en":"The advisory committee recommended reducing operational costs.","zh-TW":"諮詢委員會建議降低運營成本。"}]', '{"noun":"adviser","verb":"advise"}', NULL, 3, 162, 953),
(163, 'advisory board', '/ədˈvaɪzəri bɔːrd/', 'noun', '{"zh-TW":["顧問委員會"],"en":["a group of external advisors providing non-binding strategic guidance"]}', NULL, 'form an advisory board / advisory board member / advisory board meeting', '[{"en":"The startup assembled an advisory board of industry veterans.","zh-TW":"新創公司組建了由行業老手組成的顧問委員會。"},{"en":"The advisory board provided valuable insights on market expansion.","zh-TW":"顧問委員會提供了有關市場擴張的寶貴見解。"}]', NULL, NULL, 5, 163, NULL),
(164, 'advocate', '/ˈædvəkeɪt/', 'verb', '{"zh-TW":["提倡；擁護"],"en":["to publicly support or recommend a cause"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"voc","meaning":"call (呼叫)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"朝向呼叫支持，即「提倡」。"}', 'advocate for change/reform/rights', '[{"en":"She advocates for better working conditions.","zh-TW":"她提倡更好的工作條件。"},{"en":"Many experts advocate a gradual approach.","zh-TW":"許多專家提倡循序漸進的方式。"}]', '{"noun":"advocacy"}', NULL, 3, 164, 640),
(165, 'aerobic', '/''eəˈrəʊbɪk/', 'adjective', '{"zh-TW":["有氧的；需氧的"],"en":["relating to or denoting exercise that improves the efficiency of the body''s cardiovascular system"]}', NULL, 'aerobic exercise / aerobic capacity / aerobic fitness', '[{"en":"Jogging, swimming, and cycling are popular forms of aerobic exercise.","zh-TW":"慢跑、游泳和騎自行車是常見的有氧運動形式。"},{"en":"Improving your aerobic capacity allows you to exercise for longer periods without fatigue.","zh-TW":"提高有氧能力可讓你在不感到疲勞的情況下鍛煉更長時間。"}]', '{"noun":"aerobics"}', NULL, 3, 165, NULL),
(166, 'aerobic exercise', '/''eəˌrəʊbɪk ˈeksərsaɪz/', 'noun', '{"zh-TW":["有氧運動"],"en":["physical activity that increases the heart rate and breathing, improving cardiovascular fitness"]}', NULL, 'do aerobic exercise / regular aerobic exercise / aerobic exercise routine', '[{"en":"Thirty minutes of aerobic exercise daily significantly reduces the risk of heart disease.","zh-TW":"每天三十分鐘的有氧運動可顯著降低患心臟病的風險。"},{"en":"Walking, swimming, and cycling are all popular forms of aerobic exercise.","zh-TW":"步行、游泳和騎自行車都是受歡迎的有氧運動形式。"}]', '{"adjective":"aerobic"}', NULL, 5, 166, NULL),
(167, 'aesthetic', '/iːsˈθetɪk/', 'noun', '{"zh-TW":["美感；美學"],"en":["a set of principles underlying a work of art; visual style"]}', NULL, 'visual aesthetic / distinctive aesthetic / minimalist aesthetic', '[{"en":"The photographer developed a distinctive aesthetic centered on light and shadow.","zh-TW":"攝影師發展出一種以光影為中心的獨特美學。"},{"en":"The brand''s aesthetic appeals to young urban consumers.","zh-TW":"該品牌的美感吸引年輕的都市消費者。"}]', '{"adjective":"aesthetic","adverb":"aesthetically"}', NULL, 3, 167, NULL),
(168, 'affect', '/əˈfekt/', 'verb', '{"zh-TW":["【主要意義-動詞】影響；對……有影響","【次要意義-名詞（心理學）】情感；感情；情緒狀態","【次要意義-動詞（正式）】假裝；裝出（某種態度）"],"en":["[primary - verb] to have an effect or influence on something","[secondary - noun (psychology)] an emotion or feeling as a component of behavior","[secondary - verb] to pretend or assume something falsely"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"logic":"朝向作用，即「影響」。"}', 'affect the outcome / affect sales / flat affect / affected speech', '[{"en":"The sudden change in policy will affect all existing contract holders.","zh-TW":"政策的突然改變將影響所有現有合約持有人。"},{"en":"The patient showed signs of flat affect following the treatment.","zh-TW":"患者在治療後表現出情感平淡的跡象。"},{"en":"His affected manner of speaking annoyed some of his colleagues.","zh-TW":"他做作的說話方式令一些同事感到惱火。"}]', '{"noun":"effect (different word!)","adjective":"affected, affective"}', 'affect（動詞）= 「影響」，與 effect（名詞/動詞）區別是 TOEIC 必考文法點；名詞 affect（心理學術語 = 情感）較少見但出現在醫療文章中，affected（adj.）= 「裝出來的/做作的」。', 2, 168, 255),
(169, 'affection', '/əˈfekʃn/', 'noun', '{"zh-TW":["情感；喜愛"],"en":["a gentle feeling of fondness or love"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"對某人產生感情的狀態。"}', 'show affection / deep affection', '[{"en":"She showed great affection for her grandchildren.","zh-TW":"她對孫子們表現出極大的喜愛。"},{"en":"He has a deep affection for his hometown.","zh-TW":"他對故鄉有深厚的感情。"}]', '{"adjective":"affectionate"}', NULL, 3, 169, NULL),
(170, 'affidavit', '/ˌæfɪˈdeɪvɪt/', 'noun', '{"zh-TW":["宣誓書；書面陳述"],"en":["a written statement confirmed by oath"]}', NULL, 'sign an affidavit / sworn affidavit', '[{"en":"The witness signed an affidavit confirming the events.","zh-TW":"證人簽署了確認事件的宣誓書。"},{"en":"Submit an affidavit along with your application.","zh-TW":"請隨申請書一併提交宣誓書。"}]', NULL, NULL, 3, 170, NULL),
(171, 'affiliate', '/əˈfɪlieɪt/', 'verb', '{"zh-TW":["使隸屬；使加入","附屬機構"],"en":["to officially attach or connect to an organization"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fili","meaning":"son (子)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為兒子般的關係，即「隸屬」。"}', 'affiliate with / affiliated company', '[{"en":"The institute is affiliated with a major university.","zh-TW":"該研究所隸屬於一所主要大學。"},{"en":"Our affiliate offices handle regional operations.","zh-TW":"我們的附屬辦公室處理區域業務。"}]', '{"noun":"affiliation"}', NULL, 3, 171, 978),
(172, 'affiliate marketing', '/əˈfɪliət ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["聯盟行銷；分潤行銷"],"en":["earning commissions by promoting other companies'' products or services"]}', NULL, 'affiliate marketing program / join an affiliate program / affiliate marketing revenue', '[{"en":"The company generated 20% of sales through affiliate marketing.","zh-TW":"公司通過聯盟行銷產生了20%的銷售額。"},{"en":"Affiliate marketing is a cost-effective way to expand reach.","zh-TW":"聯盟行銷是擴大覆蓋範圍的具成本效益方式。"}]', '{"noun":"affiliate marketer"}', NULL, 5, 172, NULL),
(173, 'affiliation', '/əˌfɪliˈeɪʃən/', 'noun', '{"zh-TW":["聯繫；附屬關係"],"en":["the state of being affiliated with or connected to an organization"]}', NULL, 'professional affiliation / affiliation agreement', '[{"en":"She listed all her professional affiliations on the form.","zh-TW":"她在表格上列出了所有專業聯繫。"},{"en":"The two companies formalized their affiliation agreement.","zh-TW":"兩家公司正式簽署了附屬關係協議。"}]', '{"verb":"affiliate","adjective":"affiliated"}', NULL, 4, 173, 497),
(174, 'affinity', '/əˈfɪnɪti/', 'noun', '{"zh-TW":["親和力；共鳴"],"en":["a natural liking for and understanding of someone or something"]}', NULL, 'brand affinity / cultural affinity / affinity group', '[{"en":"Brands with strong consumer affinity outperform during market downturns.","zh-TW":"具有強烈消費者親和力的品牌在市場下行期間表現較好。"},{"en":"Cultural affinity between trading partners facilitates business relationships.","zh-TW":"貿易夥伴之間的文化親和力促進了商業關係。"}]', NULL, NULL, 3, 174, NULL),
(175, 'affirmative action', '/əˈfɜːrmətɪv ˈækʃən/', 'noun', '{"zh-TW":["積極差別待遇；平權行動"],"en":["policies promoting opportunities for underrepresented groups"]}', NULL, 'affirmative action policy / affirmative action program', '[{"en":"Affirmative action policies increased diversity in the workforce.","zh-TW":"積極差別待遇政策增加了勞動力的多元性。"},{"en":"The company adopted affirmative action measures in its hiring process.","zh-TW":"公司在招聘流程中採用了積極差別待遇措施。"}]', NULL, NULL, 5, 175, NULL),
(176, 'afford', '/əˈfɔːrd/', 'verb', '{"zh-TW":["負擔得起","提供"],"en":["to have enough money to pay for","to provide or supply"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"ford","meaning":"further (推進)"},"logic":"朝向推進足夠的，即「負擔得起」。"}', 'afford to buy/pay / can''t afford', '[{"en":"The company cannot afford to lose any more clients.","zh-TW":"公司承受不起再失去任何客戶。"},{"en":"The new location affords a beautiful view.","zh-TW":"新地點提供了美麗的景觀。"}]', '{"adjective":"affordable"}', NULL, 2, 176, 256),
(177, 'affordability', '/əˌfɔːrdəˈbɪlɪti/', 'noun', '{"zh-TW":["可負擔性"],"en":["the quality of being reasonably priced and within financial reach"]}', NULL, 'housing affordability / healthcare affordability / improve affordability', '[{"en":"Housing affordability has declined significantly in major cities.","zh-TW":"主要城市的住房可負擔性顯著下降。"},{"en":"Policy measures must address the affordability of essential medicines.","zh-TW":"政策措施必須解決基本藥物的可負擔性問題。"}]', '{"adjective":"affordable","adverb":"affordably"}', NULL, 5, 177, NULL),
(178, 'affordable', '/əˈfɔːrdəbl/', 'adjective', '{"zh-TW":["負擔得起的"],"en":["inexpensive enough for most people"]}', '{"root":{"text":"afford","meaning":"provide (提供)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠負擔的。"}', 'affordable housing / affordable price', '[{"en":"We need more affordable housing in the city.","zh-TW":"我們城市需要更多平價住宅。"},{"en":"The restaurant offers good food at affordable prices.","zh-TW":"這家餐廳以實惠的價格提供美食。"}]', '{"verb":"afford"}', NULL, 4, 178, 820),
(179, 'afforestation', '/əˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["造林；植樹造林"],"en":["the process of planting trees in an area where there was no previous forest"]}', NULL, 'afforestation program / national afforestation drive / afforestation project', '[{"en":"Afforestation programs can absorb carbon and restore degraded land.","zh-TW":"造林計畫可以吸收碳並恢復退化土地。"},{"en":"The government committed to afforestation of one million hectares by 2030.","zh-TW":"政府承諾到2030年造林一百萬公頃。"}]', '{"verb":"afforest","antonym":"deforestation"}', NULL, 5, 179, NULL),
(180, 'afraid', '/əˈfreɪd/', 'adjective', '{"zh-TW":["害怕的；恐怕","害怕的；擔心的"],"en":["feeling fear or anxiety","feeling fear; worried about something"]}', NULL, 'afraid of / I''m afraid; be afraid of / I''m afraid (that)...', '[{"en":"She is afraid of spiders.","zh-TW":"她怕蜘蛛。"},{"en":"I''m afraid I can''t help.","zh-TW":"恐怕我幫不了你。"},{"en":"I''m afraid we''re sold out.","zh-TW":"恐怕我們賣完了。"}]', NULL, NULL, 2, 180, NULL),
(181, 'after-sales service', '/ˈɑːftər seɪlz ˈsɜːrvɪs/', 'noun', '{"zh-TW":["售後服務"],"en":["support provided to customers after purchasing a product"]}', NULL, 'offer after-sales service / excellent after-sales service', '[{"en":"The company is known for its excellent after-sales service.","zh-TW":"這家公司以其卓越的售後服務而聞名。"},{"en":"After-sales service includes warranty support and repairs.","zh-TW":"售後服務包括保固支援和維修。"}]', NULL, NULL, 5, 181, NULL),
(182, 'after-tax profit', '/ˌɑːftər tæks ˈprɒfɪt/', 'noun', '{"zh-TW":["稅後利潤"],"en":["the net profit remaining after all tax payments have been deducted"]}', NULL, 'report after-tax profit / increase after-tax profit', '[{"en":"After-tax profit rose by 22% due to improved cost control.","zh-TW":"由於成本控制改善，稅後利潤增長了22%。"},{"en":"Investors compare after-tax profit margins across competitors.","zh-TW":"投資者比較競爭對手之間的稅後利潤率。"}]', '{"synonym":"net profit after tax"}', NULL, 5, 182, NULL),
(183, 'afternoon', '/ˌɑːftəˈnuːn/', 'noun', '{"zh-TW":["下午"],"en":["the period between midday and evening"]}', NULL, 'in the afternoon / this afternoon', '[{"en":"The meeting is scheduled for this afternoon.","zh-TW":"會議安排在今天下午。"},{"en":"She usually takes a nap in the afternoon.","zh-TW":"她通常在下午小睡。"}]', NULL, NULL, 3, 183, NULL),
(184, 'again', '/əˈɡɛn/', 'adverb', '{"zh-TW":["再一次；又"],"en":["one more time"]}', NULL, 'once again / again and again', '[{"en":"Please try again later.","zh-TW":"請稍後再試。"},{"en":"Once again, thank you all.","zh-TW":"再次感謝大家。"}]', '{"adverb":"again"}', NULL, 2, 184, NULL),
(185, 'against', '/əˈɡɛnst/', 'preposition', '{"zh-TW":["反對；靠著"],"en":["in opposition to","leaning on"]}', NULL, 'against the rules / go against', '[{"en":"This is against company policy.","zh-TW":"這違反公司政策。"},{"en":"He leaned against the desk.","zh-TW":"他靠在書桌上。"}]', '{"preposition":"against"}', NULL, 3, 185, NULL),
(186, 'age', '/eɪdʒ/', 'noun', '{"zh-TW":["年齡；時代"],"en":["the number of years someone has lived"]}', NULL, 'at the age of / old age', '[{"en":"She started working at the age of 18.","zh-TW":"她18歲開始工作。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"}]', '{"verb":"age","adjective":"aged"}', NULL, 1, 186, NULL),
(187, 'agency relationship', '/ˈeɪdʒənsi rɪˈleɪʃənʃɪp/', 'noun', '{"zh-TW":["代理關係"],"en":["a legal relationship where one party acts on behalf of another"]}', NULL, 'establish an agency relationship / agency relationship disclosure', '[{"en":"In an agency relationship, the agent must act in the principal''s best interest.","zh-TW":"在代理關係中，代理人必須以委托人的最佳利益行事。"},{"en":"Undisclosed agency relationships may give rise to liability for the principal.","zh-TW":"未披露的代理關係可能使委托人承擔責任。"}]', NULL, NULL, 5, 187, NULL),
(188, 'agenda', '/əˈdʒendə/', 'noun', '{"zh-TW":["議程；待辦事項"],"en":["a list of items to be discussed at a meeting"]}', '{"root":{"text":"ag","meaning":"do (做)"},"suffix":{"text":"-enda","meaning":"things to be done (待做的事)"},"logic":"待做的事，即「議程」。"}', 'meeting agenda / on the agenda', '[{"en":"The first item on the agenda is the budget review.","zh-TW":"議程上的第一項是預算審查。"},{"en":"Please distribute the agenda before the meeting.","zh-TW":"請在會議前分發議程。"}]', NULL, NULL, 2, 188, 71),
(189, 'agenda item', '/əˈdʒendə ˈaɪtəm/', 'noun', '{"zh-TW":["議程項目"],"en":["a specific topic listed for discussion in a meeting"]}', NULL, 'add an agenda item / agenda item for discussion / priority agenda item', '[{"en":"The merger was added as the first agenda item for the board meeting.","zh-TW":"合併被列為董事會議的第一個議程項目。"},{"en":"All participants may suggest agenda items before the meeting.","zh-TW":"所有與會者可在會議前提議議程項目。"}]', NULL, NULL, 4, 189, NULL),
(190, 'agenda-setting', '/əˈdʒendə ˈsetɪŋ/', 'noun', '{"zh-TW":["議程設定"],"en":["the ability to determine the topics and priorities of discussion"]}', NULL, 'agenda-setting power / agenda-setting role', '[{"en":"The chairperson has agenda-setting authority in the meeting.","zh-TW":"主席在會議中擁有議程設定權力。"},{"en":"Effective agenda-setting ensures productive meetings.","zh-TW":"有效的議程設定確保高效的會議。"}]', NULL, NULL, 5, 190, NULL),
(191, 'agent of record', '/ˈeɪdʒənt əv ˈrekərd/', 'noun', '{"zh-TW":["授權代理人；備案代理人"],"en":["the officially designated representative authorized to act on a client''s behalf"]}', NULL, 'appoint an agent of record / agent of record agreement', '[{"en":"The law firm was named agent of record for the insurance policy.","zh-TW":"律師事務所被指定為保險單的授權代理人。"},{"en":"An agent of record manages all communications with the insurer.","zh-TW":"授權代理人負責管理與保險公司的所有溝通。"}]', NULL, NULL, 5, 191, NULL),
(192, 'agentic', '/eɪˈdʒentɪk/', 'adjective', '{"zh-TW":["能動的；有主體性的"],"en":["relating to a sense of personal agency or the capacity to act independently"]}', NULL, 'agentic behavior / agentic individual / agentic approach', '[{"en":"Agentic individuals are more likely to take initiative in problem-solving.","zh-TW":"有主體性的個人更可能在解決問題時採取主動。"},{"en":"The research examines agentic and communal leadership styles.","zh-TW":"研究考察了能動型和社群型領導風格。"}]', '{"noun":"agency"}', NULL, 3, 192, NULL),
(193, 'agglomeration', '/əˌɡlɒməˈreɪʃən/', 'noun', '{"zh-TW":["聚集；積聚"],"en":["a dense clustering of firms, people, or activities in a geographic area"]}', NULL, 'urban agglomeration / industrial agglomeration / agglomeration effects', '[{"en":"Silicon Valley demonstrates the benefits of industrial agglomeration.","zh-TW":"矽谷展示了工業聚集的好處。"},{"en":"Agglomeration economies arise when firms benefit from locating near each other.","zh-TW":"當企業從相互鄰近中受益時，就會出現集聚經濟。"}]', '{"adjective":"agglomerated","verb":"agglomerate"}', NULL, 5, 193, NULL),
(194, 'aggregate', '/ˈæɡrɪɡɪt/', 'adjective', '{"zh-TW":["總計的；總體的"],"en":["formed by the combination of many items"]}', NULL, 'aggregate demand / aggregate data', '[{"en":"Aggregate sales data showed a 15% increase over last year.","zh-TW":"總計銷售數據顯示比去年增長了15%。"},{"en":"The aggregate cost of the project exceeded five million dollars.","zh-TW":"項目的總成本超過了五百萬元。"}]', '{"verb":"aggregate","noun":"aggregate"}', NULL, 3, 194, 498),
(195, 'aggregate demand', '/ˈæɡrɪɡɪt dɪˈmɑːnd/', 'noun', '{"zh-TW":["總需求"],"en":["the total demand for goods and services in an economy"]}', NULL, 'boost aggregate demand / weak aggregate demand', '[{"en":"Lower interest rates can boost aggregate demand.","zh-TW":"降低利率可以提振總需求。"},{"en":"The recession caused aggregate demand to fall significantly.","zh-TW":"經濟衰退導致總需求大幅下降。"}]', NULL, NULL, 5, 195, NULL),
(196, 'aggregate supply', '/ˈæɡrɪɡɪt səˈplaɪ/', 'noun', '{"zh-TW":["總供給"],"en":["the total amount of goods and services produced in an economy at a given price level"]}', NULL, 'stimulate aggregate supply / aggregate supply constraint', '[{"en":"Supply-side reforms aim to increase aggregate supply by reducing production costs.","zh-TW":"供給側改革旨在通過降低生產成本來增加總供給。"},{"en":"Aggregate supply fell after a severe drought damaged agricultural output.","zh-TW":"嚴重乾旱損壞農業產出後，總供給下降了。"}]', NULL, NULL, 5, 196, NULL),
(197, 'aggressive', '/əˈɡresɪv/', 'adjective', '{"zh-TW":["積極進取的","侵略的","侵略性的；積極進取的"],"en":["pursuing goals forcefully","hostile or violent"]}', '{"prefix":{"text":"ag-","meaning":"toward (朝向)"},"root":{"text":"gress","meaning":"step (踏步)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"朝向踏步的，即「積極進取的」。"}', 'aggressive strategy/marketing/growth; aggressive behavior / aggressive marketing', '[{"en":"The firm adopted an aggressive expansion strategy.","zh-TW":"該公司採用了積極的擴張策略。"},{"en":"Aggressive marketing helped boost brand awareness.","zh-TW":"積極的行銷幫助提升了品牌知名度。"},{"en":"The dog became aggressive toward strangers.","zh-TW":"這隻狗對陌生人變得有攻擊性。"},{"en":"The company adopted an aggressive marketing strategy.","zh-TW":"公司採取了積極的行銷策略。"}]', '{"noun":"aggression","adverb":"aggressively"}', NULL, 4, 197, 821),
(198, 'agile', '/ˈædʒaɪl/', 'adjective', '{"zh-TW":["敏捷的；靈活的"],"en":["able to move quickly and easily; using agile development methods"]}', NULL, 'agile team / agile approach / agile development / agile mindset', '[{"en":"The agile team delivered new features every two weeks.","zh-TW":"敏捷團隊每兩週交付新功能。"},{"en":"Staying agile allows the company to respond quickly to market changes.","zh-TW":"保持敏捷使公司能夠快速響應市場變化。"}]', '{"noun":"agility","adverb":"agilely"}', NULL, 2, 198, 822),
(199, 'agile development', '/ˈædʒaɪl dɪˈveləpmənt/', 'noun', '{"zh-TW":["敏捷開發"],"en":["an iterative approach to software development emphasizing flexibility"]}', NULL, 'adopt agile development / agile development process / agile development methodology', '[{"en":"Agile development enables teams to respond quickly to changing requirements.","zh-TW":"敏捷開發使團隊能夠快速回應不斷變化的需求。"},{"en":"The company transitioned from waterfall to agile development practices.","zh-TW":"公司從瀑布式轉型為敏捷開發實踐。"}]', NULL, NULL, 5, 199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(200, 'agile methodology', '/ˈædʒaɪl meθəˈdɒlədʒi/', 'noun', '{"zh-TW":["敏捷方法論"],"en":["an iterative approach to project management and development"]}', NULL, 'adopt agile methodology / agile methodology framework', '[{"en":"The team adopted agile methodology to speed up delivery.","zh-TW":"團隊採用敏捷方法論加快交付速度。"},{"en":"Agile methodology encourages continuous feedback and adaptation.","zh-TW":"敏捷方法論鼓勵持續反饋和適應。"}]', '{"adjective":"agile"}', NULL, 5, 200, NULL),
(201, 'agrarian', '/əˈɡreəriən/', 'adjective', '{"zh-TW":["農業的；農耕的"],"en":["relating to land, especially agricultural land or its tenure"]}', NULL, 'agrarian society / agrarian reform / agrarian economy', '[{"en":"Agrarian reforms redistributed land to poor farmers in the region.","zh-TW":"土地改革將土地重新分配給該地區的貧農。"},{"en":"The country''s transition from an agrarian to an industrial economy was rapid.","zh-TW":"這個國家從農業到工業經濟的轉型是迅速的。"}]', '{"noun":"agrarianism"}', NULL, 3, 201, NULL),
(202, 'agree', '/əˈɡriː/', 'verb', '{"zh-TW":["同意；贊成","同意；一致"],"en":["to have the same opinion; to consent","to have the same opinion","to have the same opinion; to say yes"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"gree","meaning":"pleasing (令人滿意)"},"logic":"朝向令人滿意，即「同意」。"}', 'agree on/to/with / agree to terms; agree with / agree on; agree with sb / agree to do sth / agree on sth', '[{"en":"Both parties agreed to the terms of the contract.","zh-TW":"雙方同意了合約條款。"},{"en":"I agree with your assessment of the situation.","zh-TW":"我同意你對情況的評估。"},{"en":"I agree with your suggestion.","zh-TW":"我同意你的建議。"},{"en":"They agreed on a price.","zh-TW":"他們就價格達成了一致。"},{"en":"They agreed to postpone the meeting.","zh-TW":"他們同意延後會議。"}]', '{"noun":"agreement","adjective":"agreeable"}', NULL, 2, 202, NULL),
(203, 'agreed terms', '/əˈɡriːd tɜːrmz/', 'noun', '{"zh-TW":["商定條款"],"en":["the conditions that all parties to an agreement have consented to"]}', NULL, 'finalize agreed terms / operate under agreed terms', '[{"en":"The deal was completed on agreed terms satisfactory to both parties.","zh-TW":"交易在雙方滿意的商定條款下完成了。"},{"en":"Any deviation from agreed terms must be documented in writing.","zh-TW":"對商定條款的任何偏差都必須以書面形式記錄。"}]', NULL, NULL, 4, 203, NULL),
(204, 'agreement', '/əˈɡriːmənt/', 'noun', '{"zh-TW":["協議；合約"],"en":["a formal arrangement between parties"]}', NULL, 'sign an agreement / reach an agreement', '[{"en":"Both parties signed the agreement last Monday.","zh-TW":"雙方上週一簽署了協議。"},{"en":"The terms of the agreement must be met by both sides.","zh-TW":"協議條款必須由雙方遵守。"}]', '{"verb":"agree","adjective":"agreed"}', NULL, 3, 204, 72),
(205, 'agriculture', '/ˈæɡrɪkʌltʃər/', 'noun', '{"zh-TW":["農業"],"en":["the science or practice of farming"]}', '{"root":{"text":"agri","meaning":"field (田地)"},"suffix":{"text":"culture","meaning":"cultivation (耕作)"},"logic":"耕作田地，即「農業」。"}', 'agriculture industry / sustainable agriculture', '[{"en":"Agriculture is the main industry in this region.","zh-TW":"農業是這個地區的主要產業。"},{"en":"Modern agriculture relies heavily on technology.","zh-TW":"現代農業高度依賴技術。"}]', '{"adjective":"agricultural"}', NULL, 4, 205, NULL),
(206, 'agrobiodiversity', '/ˌæɡrəʊˌbaɪəʊdaɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["農業生物多樣性"],"en":["the variety of plants, animals, and microorganisms used in agriculture"]}', NULL, 'protect agrobiodiversity / loss of agrobiodiversity / agrobiodiversity conservation', '[{"en":"Preserving agrobiodiversity strengthens food system resilience.","zh-TW":"保護農業生物多樣性增強了食物系統的韌性。"},{"en":"Monoculture farming reduces agrobiodiversity and increases crop vulnerability.","zh-TW":"單一作物農業降低了農業生物多樣性並增加了作物脆弱性。"}]', NULL, NULL, 5, 206, NULL),
(207, 'ahead', '/əˈhɛd/', 'adverb', '{"zh-TW":["在前面；提前"],"en":["in front; in advance"]}', NULL, 'go ahead / ahead of time', '[{"en":"Go ahead, I''ll catch up.","zh-TW":"你先走，我趕上。"},{"en":"We finished ahead of schedule.","zh-TW":"我們提前完成了。"}]', NULL, NULL, 2, 207, NULL),
(208, 'aid', '/eɪd/', 'noun', '{"zh-TW":["援助；幫助"],"en":["help or support","financial or material assistance"]}', '{"root":{"text":"aid","meaning":"help (幫助)"},"logic":"直接表示「援助」。"}', 'financial aid / first aid / in aid of', '[{"en":"The government provided aid to flood victims.","zh-TW":"政府向洪災受害者提供援助。"},{"en":"Visual aids can enhance presentations.","zh-TW":"視覺輔助工具可以增強簡報效果。"}]', NULL, NULL, 1, 208, NULL),
(209, 'aim', '/eɪm/', 'verb', '{"zh-TW":["目標；瞄準","旨在"],"en":["to intend or plan","to point or direct toward a target"]}', '{"root":{"text":"aim","meaning":"estimate/direct (估算/指向)"},"logic":"指向某處，即「瞄準、旨在」。"}', 'aim to do / aim at / aim for', '[{"en":"We aim to increase revenue by 20% this year.","zh-TW":"我們的目標是今年營收增長20%。"},{"en":"The campaign is aimed at young professionals.","zh-TW":"該活動針對年輕專業人士。"}]', NULL, NULL, 1, 209, NULL),
(210, 'air', '/ɛr/', 'noun', '{"zh-TW":["【主要意義-名詞】空氣；空中","【次要意義-動詞】播出；播映（節目）","【次要意義-動詞】通風；晾曬","【次要意義-動詞】表達（意見/不滿）","【次要意義-名詞】神態；樣子"],"en":["[primary - noun] the invisible mixture of gases around us","[secondary - verb] to broadcast on radio or television","[secondary - verb] to ventilate a room or dry clothes in the open air","[secondary - verb] to express an opinion or grievance openly"]}', NULL, 'air a grievance / air a program / air time / on air / put on airs', '[{"en":"The documentary will be aired on the national broadcaster next week.","zh-TW":"這部紀錄片將於下週在國家廣播機構播出。"},{"en":"Employees were given the opportunity to air their grievances at the town hall.","zh-TW":"員工在員工大會上獲得了表達不滿的機會。"},{"en":"The show will go on air live at 9 PM tonight.","zh-TW":"該節目將於今晚9點進行現場直播。"}]', '{"noun":"airway, airing","adjective":"on-air"}', 'air 作動詞：air a program（播出節目）、air a grievance（表達不滿）均是 TOEIC 媒體和職場文章的高頻用法，on air（播出中）、airtime（播出時間）也常見。', 1, 210, NULL),
(211, 'air freight', '/ɛər freɪt/', 'noun', '{"zh-TW":["空運貨物"],"en":["goods transported by air"]}', NULL, 'ship by air freight / air freight cost', '[{"en":"Air freight is used for urgent or perishable shipments.","zh-TW":"空運用於緊急或易腐貨物的運輸。"},{"en":"The air freight cost was higher than anticipated.","zh-TW":"空運成本高於預期。"}]', NULL, NULL, 4, 211, NULL),
(212, 'air quality', '/ɛər ˈkwɒlɪti/', 'noun', '{"zh-TW":["空氣品質"],"en":["the condition of the air in terms of pollutants"]}', NULL, 'monitor air quality / poor air quality', '[{"en":"Poor air quality can cause respiratory problems.","zh-TW":"空氣品質差可能導致呼吸系統問題。"},{"en":"The city has installed sensors to monitor air quality.","zh-TW":"市政府安裝了感測器來監測空氣品質。"}]', NULL, NULL, 4, 212, NULL),
(213, 'aircraft', '/ˈɛərkræft/', 'noun', '{"zh-TW":["飛機；航空器"],"en":["a vehicle able to fly"]}', NULL, 'commercial aircraft / military aircraft', '[{"en":"The aircraft landed safely despite the storm.","zh-TW":"飛機在暴風雨中安全降落。"},{"en":"Modern aircraft use advanced navigation systems.","zh-TW":"現代飛機使用先進的導航系統。"}]', '{"adjective":"airborne"}', NULL, 3, 213, NULL),
(214, 'airline', '/ˈɛərlaɪn/', 'noun', '{"zh-TW":["航空公司"],"en":["a company providing air transport services"]}', NULL, 'major airline / budget airline', '[{"en":"The airline offers daily flights to Tokyo.","zh-TW":"這家航空公司提供每日飛往東京的航班。"},{"en":"She booked her ticket through the airline website.","zh-TW":"她透過航空公司網站預訂機票。"}]', '{"verb":"fly","adjective":"aerial"}', NULL, 3, 214, NULL),
(215, 'airport', '/ˈɛərpɔːrt/', 'noun', '{"zh-TW":["機場"],"en":["a place where aircraft take off and land"]}', NULL, 'international airport / regional airport', '[{"en":"We arrived at the airport two hours before departure.","zh-TW":"我們在出發前兩小時抵達機場。"},{"en":"The new airport terminal opened last year.","zh-TW":"新的航站樓去年開幕。"}]', '{"verb":"depart"}', NULL, 3, 215, NULL),
(216, 'airport layover', '/''eərpɔːrt ˌleɪəʊvər/', 'noun', '{"zh-TW":["機場轉機等候；中途停留"],"en":["a period of time between flights spent at an intermediate airport"]}', NULL, 'long airport layover / use an airport layover / airport layover activities', '[{"en":"Her airport layover in Dubai was long enough to visit the city for a few hours.","zh-TW":"她在迪拜的機場轉機等候時間足夠長，可以在城市裡遊覽幾個小時。"},{"en":"She used her airport layover to relax in the lounge and catch up on work.","zh-TW":"她利用機場轉機等候時間在貴賓室休息並處理工作。"}]', '{"noun":"layover"}', NULL, 5, 216, NULL),
(217, 'airway bill', '/''eərweɪ bɪl/', 'noun', '{"zh-TW":["航空運單"],"en":["a document issued by an airline carrier which provides detailed information about a shipment sent via air freight"]}', NULL, 'issue an airway bill / airway bill number / original airway bill', '[{"en":"The airway bill serves as both a receipt and a contract for air cargo shipment.","zh-TW":"航空運單既作為空運貨物運輸的收據，也作為合同。"},{"en":"She tracked her shipment using the airway bill number provided by the carrier.","zh-TW":"她使用承運人提供的航空運單號碼追蹤她的貨物。"}]', NULL, NULL, 4, 217, NULL),
(218, 'aisle', '/aɪl/', 'noun', '{"zh-TW":["走道；通道"],"en":["a passage between rows of shelves or seats"]}', '{"root":{"text":"aisle","meaning":"passage (通道)"},"logic":"源自拉丁語 ala（翼），指建築內的側通道。"}', 'walk down the aisle / aisle seat', '[{"en":"You can find the cereal in aisle three.","zh-TW":"你可以在第三走道找到麥片。"},{"en":"She prefers an aisle seat on the plane.","zh-TW":"她偏好飛機上的走道座位。"}]', NULL, NULL, 2, 218, NULL),
(219, 'aisle seat', '/aɪl siːt/', 'noun', '{"zh-TW":["走道座位"],"en":["a seat next to the aisle in a plane"]}', NULL, 'prefer an aisle seat / request an aisle seat', '[{"en":"I always request an aisle seat for long flights.","zh-TW":"我長途飛行都要求走道座位。"},{"en":"The aisle seat gives you more legroom.","zh-TW":"走道座位給您更多腿部空間。"}]', NULL, NULL, 4, 219, NULL),
(220, 'alert', '/əˈlɜːrt/', 'adjective', '{"zh-TW":["警覺的；警報"],"en":["quick to notice and respond to danger"]}', '{"root":{"text":"alert","meaning":"on the watch (警戒)"},"logic":"源自義大利語 all''erta（在瞭望台上）。"}', 'stay alert / alert system / high alert', '[{"en":"Drivers should stay alert at all times.","zh-TW":"駕駛人應隨時保持警覺。"},{"en":"The system sends an alert when errors occur.","zh-TW":"系統在發生錯誤時發送警報。"}]', '{"noun":"alert","verb":"alert"}', NULL, 2, 220, 258),
(221, 'algorithm', '/ˈælɡərɪðəm/', 'noun', '{"zh-TW":["演算法"],"en":["a set of rules for solving a problem"]}', NULL, 'search algorithm / algorithm design', '[{"en":"The algorithm sorts data efficiently.","zh-TW":"這個演算法能有效地排序資料。"},{"en":"Social media algorithms control what you see.","zh-TW":"社群媒體演算法控制你看到的內容。"}]', '{"adjective":"algorithmic"}', NULL, 3, 221, NULL),
(222, 'algorithm complexity', '/ˈælɡərɪðəm kəmˈpleksɪti/', 'noun', '{"zh-TW":["算法複雜度"],"en":["a measure of the computing resources required by an algorithm"]}', NULL, 'analyze algorithm complexity / reduce algorithm complexity / Big-O algorithm complexity', '[{"en":"Understanding algorithm complexity helps developers choose efficient solutions.","zh-TW":"理解算法複雜度幫助開發者選擇高效的解決方案。"},{"en":"The sorting algorithm has O(n log n) complexity.","zh-TW":"這個排序算法具有O(n log n)的複雜度。"}]', NULL, NULL, 5, 222, NULL),
(223, 'alienation', '/ˌeɪliəˈneɪʃən/', 'noun', '{"zh-TW":["疏離感；異化"],"en":["the state of being isolated from a group or activity you should be involved in"]}', NULL, 'social alienation / worker alienation / sense of alienation', '[{"en":"Marx argued that industrial capitalism causes worker alienation from their labor.","zh-TW":"馬克思認為工業資本主義導致工人對勞動的異化。"},{"en":"Political alienation among youth leads to low voter turnout.","zh-TW":"青年的政治疏離感導致了低投票率。"}]', '{"verb":"alienate","adjective":"alienated"}', NULL, 4, 223, NULL),
(224, 'align', '/əˈlaɪn/', 'verb', '{"zh-TW":["對齊；使一致"],"en":["to arrange things in a line or to ensure consistency between things"]}', NULL, 'align goals / align teams / align with strategy', '[{"en":"The new policy aligns employee incentives with company objectives.","zh-TW":"新政策使員工激勵與公司目標保持一致。"},{"en":"The departments aligned their priorities before the budget review.","zh-TW":"各部門在預算審查前調整了其優先事項。"}]', '{"noun":"alignment","adjective":"aligned"}', NULL, 2, 224, 641),
(225, 'alive', '/əˈlaɪv/', 'adjective', '{"zh-TW":["活著的；有生氣的","活著的；有活力的","活著的；活躍的"],"en":["living; not dead","full of energy","living; full of energy"]}', NULL, 'stay alive / come alive', '[{"en":"The tradition is still alive today.","zh-TW":"這個傳統至今仍然存在。"},{"en":"The market comes alive on weekends.","zh-TW":"市場在週末變得熱鬧起來。"},{"en":"He was found alive after three days.","zh-TW":"三天後他被發現還活著。"},{"en":"The city comes alive at night.","zh-TW":"城市在夜晚活躍起來。"},{"en":"He is lucky to be alive after the accident.","zh-TW":"他在事故後還活著很幸運。"},{"en":"The city comes alive at night.","zh-TW":"這座城市在夜晚變得活躍起來。"}]', '{"adjective":"alive"}', NULL, 2, 225, NULL),
(226, 'all-in cost', '/ɔːl ɪn kɒst/', 'noun', '{"zh-TW":["綜合成本；全包成本"],"en":["the total cost including all fees, charges, and expenses"]}', NULL, 'calculate all-in cost / all-in cost comparison', '[{"en":"The all-in cost of the loan included processing and insurance fees.","zh-TW":"貸款的綜合成本包括處理費和保險費。"},{"en":"Compare the all-in cost of leasing versus buying before deciding.","zh-TW":"在決定之前比較租賃和購買的綜合成本。"}]', NULL, NULL, 4, 226, NULL),
(227, 'all-inclusive', '/''ɔːl ɪnˈkluːsɪv/', 'adjective', '{"zh-TW":["全包式的；一切費用包括在內的"],"en":["including everything, especially all meals and drinks within a single price"]}', NULL, 'all-inclusive resort / all-inclusive package / all-inclusive deal', '[{"en":"The all-inclusive resort covered accommodation, meals, drinks, and activities.","zh-TW":"這個全包式度假村涵蓋了住宿、餐食、飲料和活動。"},{"en":"All-inclusive packages are popular with families who want to budget in advance.","zh-TW":"全包式套餐對希望提前預算的家庭很受歡迎。"}]', NULL, NULL, 5, 227, NULL),
(228, 'allegation', '/ˌæləˈɡeɪʃən/', 'noun', '{"zh-TW":["指控；指稱"],"en":["a claim that someone has done something wrong, without proof"]}', NULL, 'make an allegation / deny the allegation / allegation of fraud', '[{"en":"The allegation of fraud triggered an internal investigation.","zh-TW":"詐欺指控引發了內部調查。"},{"en":"She denied all allegations made against her.","zh-TW":"她否認了針對她的所有指控。"}]', '{"verb":"allege","adjective":"alleged"}', NULL, 4, 228, NULL),
(229, 'allegory', '/ˈæləɡɒri/', 'noun', '{"zh-TW":["寓言；暗喻"],"en":["a story, poem, or picture that can be interpreted to reveal a hidden meaning"]}', NULL, 'political allegory / religious allegory / read as an allegory', '[{"en":"The novel is often read as an allegory for colonialism and resistance.","zh-TW":"這部小說常被解讀為殖民主義和抵抗的寓言。"},{"en":"The film works both as entertainment and as a powerful allegory.","zh-TW":"這部電影既可作為娛樂，也可作為強有力的寓言。"}]', '{"adjective":"allegorical","adverb":"allegorically"}', NULL, 3, 229, NULL),
(230, 'allergen', '/ˈælədʒən/', 'noun', '{"zh-TW":["過敏原"],"en":["a substance that causes an allergic reaction"]}', NULL, 'common allergen / allergen information', '[{"en":"Please inform the server of any allergens before ordering.","zh-TW":"點餐前請告知服務員任何過敏原。"},{"en":"The menu clearly lists all allergens in each dish.","zh-TW":"菜單清楚列出每道菜的所有過敏原。"}]', '{"adjective":"allergenic","noun":"allergy"}', NULL, 3, 230, NULL),
(231, 'allergy', '/ˈælərdʒi/', 'noun', '{"zh-TW":["過敏症"],"en":["an adverse reaction of the immune system to a substance"]}', NULL, 'food allergy / seasonal allergy', '[{"en":"She has a severe allergy to peanuts.","zh-TW":"她對花生有嚴重過敏症。"},{"en":"Please inform your doctor about all known allergies.","zh-TW":"請告知您的醫生所有已知的過敏症。"}]', '{"adjective":"allergic","noun":"allergen"}', NULL, 3, 231, NULL),
(232, 'alliance', 'əˈlaɪəns', 'noun', '{"zh-TW":["聯盟；結盟","同盟"],"en":["a formal agreement between parties","a partnership"]}', NULL, 'strategic alliance/form an alliance', '[{"en":"We formed a strategic alliance with our partner.","zh-TW":"我們與合作夥伴建立了戰略聯盟。"}]', '{"adjective":"allied"}', NULL, 3, 232, NULL),
(233, 'allocate', '/ˈæləkeɪt/', 'verb', '{"zh-TW":["分配；撥出","分配"],"en":["to distribute resources for a particular purpose","to distribute for a particular purpose"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"loc","meaning":"place (地方)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向特定地方，即「分配」。"}', 'allocate funds/resources/budget; allocate resources / allocate funds', '[{"en":"The company allocated $2 million for R&D.","zh-TW":"公司撥出200萬美元用於研發。"},{"en":"Resources should be allocated based on priority.","zh-TW":"資源應根據優先順序分配。"},{"en":"The government allocated funds for education.","zh-TW":"政府撥款用於教育。"},{"en":"We need to allocate more time to this project.","zh-TW":"我們需要為這個專案分配更多時間。"}]', '{"noun":"allocation"}', NULL, 3, 233, 4),
(234, 'allocation', '/ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["分配；撥款"],"en":["the distribution of resources, funds, or tasks to specific purposes"]}', NULL, 'budget allocation / resource allocation / allocation of funds', '[{"en":"Fair allocation of tasks prevented burnout in the team.","zh-TW":"公平的任務分配防止了團隊倦怠。"},{"en":"Budget allocation decisions are made at the executive level.","zh-TW":"預算分配決策在高管層面做出。"}]', '{"verb":"allocate","adjective":"allocated"}', NULL, 4, 234, 500),
(235, 'allocation method', '/ˌæləˈkeɪʃən ˈmeθəd/', 'noun', '{"zh-TW":["分配方法"],"en":["the approach used to distribute costs, resources, or responsibilities"]}', NULL, 'select an allocation method / apply the allocation method', '[{"en":"The company uses activity-based allocation methods for overhead costs.","zh-TW":"公司對間接費用使用基於活動的分配方法。"},{"en":"Choosing the right allocation method is critical for accurate pricing.","zh-TW":"選擇正確的分配方法對於準確定價至關重要。"}]', NULL, NULL, 5, 235, NULL),
(236, 'allocation of resources', '/ˌæləˈkeɪʃən əv rɪˈsɔːrsɪz/', 'noun', '{"zh-TW":["資源分配"],"en":["the process of deciding how to distribute available resources across activities"]}', NULL, 'optimize allocation of resources / allocation of resources decision', '[{"en":"Efficient allocation of resources maximizes organizational output.","zh-TW":"有效的資源分配最大化了組織產出。"},{"en":"The annual plan includes an allocation of resources to each department.","zh-TW":"年度計劃包括向每個部門的資源分配。"}]', NULL, NULL, 5, 236, NULL),
(237, 'allotment', '/əˈlɒtmənt/', 'noun', '{"zh-TW":["分配；配額；配售"],"en":["the distribution of shares or resources among applicants or participants"]}', NULL, 'allotment of shares / allotment notice / allotment of resources', '[{"en":"Employees received an allotment of shares at the company''s IPO.","zh-TW":"員工在公司首次公開招股時獲得了股份配售。"},{"en":"The budget committee approved the allotment of funds to each department.","zh-TW":"預算委員會批准了向各部門的資金分配。"}]', '{"verb":"allot","adjective":"allotted"}', NULL, 3, 237, 745),
(238, 'allow', '/əˈlaʊ/', 'verb', '{"zh-TW":["允許；准許","允許；容許"],"en":["to give permission for","to make something possible","to let someone do something","to give permission; to make it possible"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"low","meaning":"approve (批准)"},"logic":"朝向批准，即「允許」。"}', 'allow sb to do / allow for; allow for / not allowed; allow sb to do sth / be allowed to', '[{"en":"The policy allows employees to work from home.","zh-TW":"該政策允許員工在家工作。"},{"en":"Please allow 3-5 business days for processing.","zh-TW":"請預留3-5個工作天處理。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不准吸煙。"},{"en":"Allow two weeks for delivery.","zh-TW":"請預留兩週送貨時間。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不允許吸菸。"},{"en":"Please allow two weeks for delivery.","zh-TW":"請預留兩週的配送時間。"}]', '{"noun":"allowance","adjective":"allowable"}', NULL, 2, 238, NULL),
(239, 'allowance', 'əˈlaʊəns', 'noun', '{"zh-TW":["津貼；補貼","額度"],"en":["a regular amount of money","an amount permitted"]}', NULL, 'travel allowance/housing allowance', '[{"en":"You are entitled to a travel allowance.","zh-TW":"您有權獲得差旅津貼。"}]', '{"verb":"allow","adjective":"allowable"}', NULL, 3, 239, 259),
(240, 'allowance for doubtful accounts', '/əˈlaʊəns fɔːr ˈdaʊtfəl əˈkaʊnts/', 'noun', '{"zh-TW":["呆帳準備金"],"en":["a reserve established to account for receivables that may not be collected"]}', NULL, 'set up an allowance for doubtful accounts / review allowance for doubtful accounts', '[{"en":"The accountant increased the allowance for doubtful accounts after reviewing aging.","zh-TW":"會計師在審查帳齡後增加了呆帳準備金。"},{"en":"An allowance for doubtful accounts reduces net receivables on the balance sheet.","zh-TW":"呆帳準備金降低了資產負債表上的淨應收帳款。"}]', NULL, NULL, 5, 240, NULL),
(241, 'alone', '/əˈloʊn/', 'adjective', '{"zh-TW":["獨自的；單獨的","單獨的；獨自的","獨自的；單獨地"],"en":["without other people","without other people; only"]}', NULL, 'leave alone / stand alone; leave alone / all alone; leave sb alone / let alone (更不用說)', '[{"en":"She prefers to work alone.","zh-TW":"她偏好獨自工作。"},{"en":"You are not alone in this.","zh-TW":"你不是一個人面對這件事。"},{"en":"She lives alone.","zh-TW":"她獨自生活。"},{"en":"Leave me alone, please.","zh-TW":"請讓我一個人待著。"},{"en":"She lives alone in a small apartment.","zh-TW":"她獨自住在一間小公寓裡。"},{"en":"Leave me alone, please.","zh-TW":"請別打擾我。"}]', '{"adjective":"alone","adverb":"alone"}', NULL, 2, 241, NULL),
(242, 'along', '/əˈlɒŋ/', 'preposition', '{"zh-TW":["沿著；一起"],"en":["moving forward on"]}', NULL, 'along with / get along', '[{"en":"We walked along the river.","zh-TW":"我們沿著河邊散步。"},{"en":"She gets along with everyone.","zh-TW":"她和每個人都相處得很好。"}]', NULL, NULL, 2, 242, NULL),
(243, 'already', '/ɔːlˈrɛdi/', 'adverb', '{"zh-TW":["已經"],"en":["before now or a specified time","before now or before a particular time"]}', NULL, 'already done / already know; already + 完成式', '[{"en":"The report is already finished.","zh-TW":"報告已經完成了。"},{"en":"We have already discussed this.","zh-TW":"我們已經討論過這件事了。"},{"en":"I''ve already eaten lunch.","zh-TW":"我已經吃過午餐了。"},{"en":"She already knows the answer.","zh-TW":"她已經知道答案了。"},{"en":"I''ve already finished my homework.","zh-TW":"我已經完成作業了。"},{"en":"The train had already left when we arrived.","zh-TW":"我們到達時火車已經開走了。"}]', '{"adverb":"already"}', NULL, 3, 243, NULL),
(244, 'also', '/ˈɔːlsoʊ/', 'adverb', '{"zh-TW":["也；而且"],"en":["in addition; too"]}', NULL, 'also known as / but also', '[{"en":"He also speaks French.","zh-TW":"他也說法語。"},{"en":"She is not only smart but also kind.","zh-TW":"她不僅聰明而且善良。"}]', NULL, NULL, 1, 244, NULL),
(245, 'alter', '/ˈɔːltər/', 'verb', '{"zh-TW":["改變；修改"],"en":["to change or make different"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"logic":"使成為其他樣子，即「改變」。"}', 'alter plans/design/course', '[{"en":"The company altered its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"Circumstances may alter the timeline.","zh-TW":"情況可能改變時間表。"}]', '{"noun":"alteration","adjective":"alternate"}', NULL, 2, 245, NULL),
(246, 'alternative', '/ɔːlˈtɜːrnətɪv/', 'noun', '{"zh-TW":["替代方案；選擇"],"en":["one of two or more available possibilities"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"suffix":{"text":"-ative","meaning":"relating to (有關的)"},"logic":"與其他有關的，即「替代方案」。"}', 'alternative solution/approach/option', '[{"en":"We need to find an alternative to the current supplier.","zh-TW":"我們需要找到目前供應商的替代方案。"},{"en":"What are the alternatives if the deal falls through?","zh-TW":"如果交易失敗，有什麼替代方案？"}]', '{"adverb":"alternatively"}', NULL, 4, 246, 260),
(247, 'alternatively', '/ɔːlˈtɜːrnətɪvli/', 'adverb', '{"zh-TW":["或者；作為替代"],"en":["in a way that offers a choice between two or more things"]}', NULL, 'alternatively, you may / choose alternatively', '[{"en":"You can pay online, or alternatively, at our office.","zh-TW":"您可以在線支付，或者也可以在我們的辦公室支付。"},{"en":"We can meet on Tuesday, or alternatively on Friday.","zh-TW":"我們可以在週二會面，或者也可以在週五。"}]', '{"adjective":"alternative","noun":"alternative"}', NULL, 5, 247, NULL),
(248, 'although', '/ɔːlˈðoʊ/', 'conjunction', '{"zh-TW":["雖然；儘管"],"en":["despite the fact that"]}', NULL, 'although... still; although = though (較口語)', '[{"en":"Although it rained, we went out.","zh-TW":"雖然下雨了，我們還是出門了。"},{"en":"Although tired, she kept working.","zh-TW":"雖然累了，她仍繼續工作。"},{"en":"Although it was raining, we went out.","zh-TW":"雖然在下雨，我們還是出去了。"},{"en":"Although expensive, the product is worth it.","zh-TW":"雖然貴，但這個產品值得。"}]', NULL, NULL, 3, 248, NULL),
(249, 'altitude', '/''æltɪtjuːd/', 'noun', '{"zh-TW":["海拔；高度"],"en":["the height of an object or point in relation to sea level"]}', NULL, 'high altitude / altitude sickness / gain altitude', '[{"en":"Travelers visiting high-altitude destinations should allow time to acclimatize.","zh-TW":"前往高海拔目的地的旅客應給自己時間適應。"},{"en":"The plane cruised at an altitude of thirty-five thousand feet.","zh-TW":"飛機在三萬五千英尺的高度巡航。"}]', NULL, NULL, 3, 249, NULL);